package com.example.yuejie;

import android.content.*;
import android.database.Cursor;
import android.database.sqlite.*;
import org.json.*;
import java.util.*;

final class LocalLibrary extends SQLiteOpenHelper {
  static final long CACHE_LIMIT=50L*1024*1024;
  final Context context;
  LocalLibrary(Context c){super(c.getApplicationContext(),"reading-dog.db",null,2);context=c.getApplicationContext();migrate();}
  void createUpdates(SQLiteDatabase db){db.execSQL("CREATE TABLE IF NOT EXISTS library_updates(book TEXT PRIMARY KEY, checked_at INTEGER NOT NULL, acknowledged_tail TEXT NOT NULL)");}
  public void onCreate(SQLiteDatabase db){createUpdates(db);db.execSQL("CREATE TABLE books(id TEXT PRIMARY KEY, json TEXT NOT NULL, added INTEGER NOT NULL, last_read INTEGER NOT NULL DEFAULT 0)");db.execSQL("CREATE TABLE progress(book TEXT PRIMARY KEY, chapter TEXT NOT NULL, offset INTEGER NOT NULL, chapter_index INTEGER NOT NULL, total INTEGER NOT NULL, title TEXT, updated INTEGER NOT NULL)");db.execSQL("CREATE TABLE directories(book TEXT PRIMARY KEY, json TEXT NOT NULL)");db.execSQL("CREATE TABLE chapters(book TEXT, chapter TEXT, json TEXT NOT NULL, bytes INTEGER NOT NULL, used INTEGER NOT NULL, PRIMARY KEY(book,chapter))");db.execSQL("CREATE TABLE bookmarks(book TEXT, chapter TEXT, offset INTEGER, title TEXT, created INTEGER, PRIMARY KEY(book,chapter,offset))");}
  public void onUpgrade(SQLiteDatabase db,int from,int to){if(from<2)createUpdates(db);}
  void migrate(){SharedPreferences p=context.getSharedPreferences("reading_dog",0);if(p.getBoolean("sqlite_migrated",false))return;SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{JSONArray a=new JSONArray(p.getString("books_v2","[]"));for(int i=0;i<a.length();i++){Book b=new Book(a.getJSONObject(i));if(!b.id.isEmpty()&&!b.title.isEmpty())add(b);}db.setTransactionSuccessful();}catch(Exception e){android.util.Log.e("ReadingDogStore","Shelf migration failed; original retained",e);return;}finally{db.endTransaction();}p.edit().putBoolean("sqlite_migrated",true).commit();}
  synchronized void add(Book b){ContentValues v=new ContentValues();v.put("id",b.id);v.put("json",b.raw.toString());v.put("added",System.currentTimeMillis());getWritableDatabase().insertWithOnConflict("books",null,v,SQLiteDatabase.CONFLICT_IGNORE);}
  synchronized void updateBook(Book b){ContentValues v=new ContentValues();v.put("json",b.raw.toString());getWritableDatabase().update("books",v,"id=?",new String[]{b.id});}
  boolean contains(String id){try(Cursor c=getReadableDatabase().rawQuery("SELECT 1 FROM books WHERE id=?",new String[]{id})){return c.moveToFirst();}}
  Book book(String id){try(Cursor c=getReadableDatabase().rawQuery("SELECT json FROM books WHERE id=?",new String[]{id})){return c.moveToFirst()?new Book(new JSONObject(c.getString(0))):null;}catch(JSONException e){return null;}}
  void remove(String id){getWritableDatabase().delete("books","id=?",new String[]{id});}
  List<Book> books(boolean recent){List<Book> out=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT json FROM books ORDER BY "+(recent?"last_read DESC, added DESC":"added DESC"),null)){while(c.moveToNext())try{out.add(new Book(new JSONObject(c.getString(0))));}catch(JSONException ignored){}}return out;}
  JSONObject progress(String id){try(Cursor c=getReadableDatabase().rawQuery("SELECT chapter,offset,chapter_index,total,title FROM progress WHERE book=?",new String[]{id})){if(c.moveToFirst())return new JSONObject().put("chapter",c.getString(0)).put("offset",c.getInt(1)).put("index",c.getInt(2)).put("total",c.getInt(3)).put("title",c.getString(4));}catch(JSONException ignored){}return null;}
  void progress(String book,String chapter,int offset,int index,int total,String title){ContentValues v=new ContentValues();long now=System.currentTimeMillis();v.put("book",book);v.put("chapter",chapter);v.put("offset",offset);v.put("chapter_index",index);v.put("total",total);v.put("title",title);v.put("updated",now);getWritableDatabase().insertWithOnConflict("progress",null,v,SQLiteDatabase.CONFLICT_REPLACE);ContentValues b=new ContentValues();b.put("last_read",now);getWritableDatabase().update("books",b,"id=?",new String[]{book});acknowledgeRead(book,chapter);}
  JSONArray directory(String book){try(Cursor c=getReadableDatabase().rawQuery("SELECT json FROM directories WHERE book=?",new String[]{book})){return c.moveToFirst()?new JSONArray(c.getString(0)):null;}catch(JSONException e){return null;}}
  synchronized void directory(String book,JSONArray data){SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{if(contains(book)){JSONArray old=directory(book);Book previous=book(book);int previousCount=previous==null?0:previous.raw.optInt("chapter_count");int baselineIndex=previousCount>0?Math.min(previousCount,data.length())-1:data.length()-1;String baseline=old!=null&&old.length()>0?old.optJSONObject(old.length()-1).optString("id"):data.optJSONObject(baselineIndex).optString("id");ContentValues initial=new ContentValues();initial.put("book",book);initial.put("checked_at",System.currentTimeMillis());initial.put("acknowledged_tail",baseline);db.insertWithOnConflict("library_updates",null,initial,SQLiteDatabase.CONFLICT_IGNORE);ContentValues checked=new ContentValues();checked.put("checked_at",System.currentTimeMillis());db.update("library_updates",checked,"book=?",new String[]{book});}ContentValues v=new ContentValues();v.put("book",book);v.put("json",data.toString());db.insertWithOnConflict("directories",null,v,SQLiteDatabase.CONFLICT_REPLACE);db.setTransactionSuccessful();}finally{db.endTransaction();}}
  synchronized void acknowledgeRead(String book,String chapter){JSONArray dir=directory(book);if(dir==null)return;String ack="";try(Cursor c=getReadableDatabase().rawQuery("SELECT acknowledged_tail FROM library_updates WHERE book=?",new String[]{book})){if(c.moveToFirst())ack=c.getString(0);else return;}int baseline=-1,read=-1;for(int i=0;i<dir.length();i++){String id=dir.optJSONObject(i).optString("id");if(id.equals(ack))baseline=i;if(id.equals(chapter))read=i;}if(baseline>=0&&read>baseline){ContentValues values=new ContentValues();values.put("acknowledged_tail",chapter);getWritableDatabase().update("library_updates",values,"book=?",new String[]{book});}}
  long checkedAt(String book){try(Cursor c=getReadableDatabase().rawQuery("SELECT checked_at FROM library_updates WHERE book=?",new String[]{book})){return c.moveToFirst()?c.getLong(0):0;}}
  static final class CatalogStatus {int total,current,newChapters;String latestTitle="";boolean currentFound;}
  CatalogStatus catalogStatus(Book book,JSONObject position){CatalogStatus info=new CatalogStatus();if(book==null)return info;JSONArray dir=directory(book.id);info.total=dir==null?Math.max(book.raw.optInt("chapter_count"),position==null?0:position.optInt("total")):dir.length();info.current=position==null?0:position.optInt("index")+1;String acknowledged="";try(Cursor c=getReadableDatabase().rawQuery("SELECT acknowledged_tail FROM library_updates WHERE book=?",new String[]{book.id})){if(c.moveToFirst())acknowledged=c.getString(0);}int known=-1,read=-1;if(dir!=null){for(int i=0;i<dir.length();i++){String id=dir.optJSONObject(i).optString("id");if(id.equals(acknowledged))known=i;if(position!=null&&id.equals(position.optString("chapter"))){read=i;info.current=i+1;info.currentFound=true;}}if(dir.length()>0)info.latestTitle=dir.optJSONObject(dir.length()-1).optString("title");if(known>=0)info.newChapters=Math.max(0,dir.length()-1-Math.max(known,read));}return info;}

  boolean hasChapter(String book,String chapter){try(Cursor c=getReadableDatabase().rawQuery("SELECT 1 FROM chapters WHERE book=? AND chapter=?",new String[]{book,chapter})){return c.moveToFirst();}}
  synchronized JSONObject chapter(String book,String chapter){try(Cursor c=getReadableDatabase().rawQuery("SELECT json FROM chapters WHERE book=? AND chapter=?",new String[]{book,chapter})){if(!c.moveToFirst())return null;JSONObject o=new JSONObject(c.getString(0));ContentValues v=new ContentValues();v.put("used",System.currentTimeMillis());getWritableDatabase().update("chapters",v,"book=? AND chapter=?",new String[]{book,chapter});return o;}catch(JSONException e){getWritableDatabase().delete("chapters","book=? AND chapter=?",new String[]{book,chapter});return null;}}
  synchronized void chapter(String book,String chapter,JSONObject data){String json=data.toString();ContentValues v=new ContentValues();v.put("book",book);v.put("chapter",chapter);v.put("json",json);v.put("bytes",ProtocolCrypto.utf(json).length);v.put("used",System.currentTimeMillis());SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{db.insertWithOnConflict("chapters",null,v,SQLiteDatabase.CONFLICT_REPLACE);long size;try(Cursor c=db.rawQuery("SELECT COALESCE(SUM(bytes),0) FROM chapters",null)){c.moveToFirst();size=c.getLong(0);}try(Cursor c=db.rawQuery("SELECT book,chapter,bytes FROM chapters ORDER BY used ASC",null)){while(size>CACHE_LIMIT&&c.moveToNext()){db.delete("chapters","book=? AND chapter=?",new String[]{c.getString(0),c.getString(1)});size-=c.getLong(2);}}db.setTransactionSuccessful();}finally{db.endTransaction();}}
  boolean bookmark(String book,String chapter,int offset){try(Cursor c=getReadableDatabase().rawQuery("SELECT 1 FROM bookmarks WHERE book=? AND chapter=? AND offset=?",new String[]{book,chapter,Integer.toString(offset)})){return c.moveToFirst();}}
  void toggleBookmark(String book,String chapter,int offset,String title){if(bookmark(book,chapter,offset)){getWritableDatabase().delete("bookmarks","book=? AND chapter=? AND offset=?",new String[]{book,chapter,Integer.toString(offset)});return;}ContentValues v=new ContentValues();v.put("book",book);v.put("chapter",chapter);v.put("offset",offset);v.put("title",title);v.put("created",System.currentTimeMillis());getWritableDatabase().insertOrThrow("bookmarks",null,v);}
  List<JSONObject> bookmarks(String book){List<JSONObject> out=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT chapter,offset,title FROM bookmarks WHERE book=? ORDER BY created DESC",new String[]{book})){while(c.moveToNext())try{out.add(new JSONObject().put("chapter",c.getString(0)).put("offset",c.getInt(1)).put("title",c.getString(2)));}catch(JSONException ignored){}}return out;}
}
